from pathlib import Path
import base64,json
R=Path(__file__).resolve().parents[2];O=R/'renders/references_calques_v2';m=json.loads((O/'manifest.json').read_text())
def uri(p):return 'data:image/png;base64,'+base64.b64encode((O/p).read_bytes()).decode()
d={'terrains':{},'backgrounds':{},'stars':[uri(Path('etoiles')/f'{i:02}.png') for i in range(64)],'halo':[uri(Path('astres/halo')/f'{i:02}.png') for i in range(64)],'moon':uri(Path('astres/lune.png')),'reflets':{k:[uri(Path('reflets')/k/'frames'/f'{i:02}.png') for i in range(64)] for k in ['soleil','lune']}}
for t in m['terrains']:d['terrains'][t['id']]={**t,'jour':uri(Path('falaises')/t['id']/'calque_jour.png'),'nuit':uri(Path('falaises')/t['id']/'calque_nuit.png')}
for mode in m['backgrounds']:d['backgrounds'][mode]={n:uri(Path('fonds')/mode/f) for n,f in [('sky','01_ciel.png'),('sea','05_mer.png'),('clouds','03_nuages_wrap.png')]};d['backgrounds'][mode]['sun']=uri(Path('fonds/coucher/04_soleil.png'))
html='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Côte Métano · atelier multicouche V2</title><style>*{box-sizing:border-box}body{margin:0;background:#101823;color:#eef1f6;font:15px system-ui}header,main,footer{max-width:1340px;margin:auto;padding:24px}header{border-bottom:1px solid #344154}h1{font-size:27px;margin:5px 0}p{color:#becada;line-height:1.6}.badge{color:#77dfd0;font-size:12px;letter-spacing:2px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}button,select{background:#24354a;color:#eef1f6;border:1px solid #50627c;border-radius:7px;padding:10px;cursor:pointer}.workspace{display:grid;grid-template-columns:1fr 230px;gap:22px}canvas{width:100%;background:#202c3b;image-rendering:pixelated;border:1px solid #44566f}aside{padding:15px;background:#192637;border-radius:8px}label{display:block;margin:12px 0}a{color:#94e6db}#audit{color:#f1cd96}small{color:#aebcd0}.cards{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.cards button.active{border:2px solid #6be0cf}footer{border-top:1px solid #344154}@media(max-width:850px){.workspace{grid-template-columns:1fr}aside{display:flex;gap:15px;flex-wrap:wrap}}</style><header><div class="badge">CÔTE MÉTANO / CALQUES V2</div><h1>10 promontoires · ciel & animations séparées</h1><p>Base côtière V2 restaurée. Reflets issus de planches générées PMD, étoiles et halo indépendants, nuages en wrap continu. Propositions graphiques — pas un mod natif validé.</p></header><main><div class="toolbar"><select id="mode"><option value="jour">Jour · dégradé du ZIP</option><option value="coucher">Coucher de soleil</option><option value="nuit" selected>Nuit · lune</option></select><button id="pause">Pause</button><button id="reset">Revenir au début</button><button id="png">Exporter la composition PNG</button></div><div class="workspace"><section><canvas id="view" width="960" height="600"></canvas><p id="clock"></p><p id="audit"></p></section><aside id="toggles"></aside></div><div class="cards" id="cards"></div><p>Les astres et leur reflet sont placés du côté dégagé de la falaise. Les PNG de terrain restent à leur orientation d’origine. Le dégradé du coucher reprend les paliers du ciel V2 avec des teintes dérivées ; la nuit utilise le filtre Abyss.</p></main><footer><b>Planches et sources</b><p>Dans <code>renders/references_calques_v2/</code> : <code>planches/</code> (étoiles, halo, reflets), <code>reflets/</code> (8 clés + 64 phases), <code>falaises/01…10/</code>, <code>fonds/</code> et <code>manifest.json</code>. Les exports originaux et la V1 sont conservés.</p><small>Les nuages bouclent spatialement tous les 960 px à −4 px/s (240 s), sans retour brutal toutes les 64 phases. Les aperçus WebP courts ne montrent que les animations de lumière ; le wrap est actif ici.</small></footer><script>const DATA=__DATA__;function image(s){let i=new Image();i.src=s;return i}const stars=DATA.stars.map(image),halo=DATA.halo.map(image),moon=image(DATA.moon),reflets=Object.fromEntries(Object.entries(DATA.reflets).map(([k,v])=>[k,v.map(image)])),bg=Object.fromEntries(Object.entries(DATA.backgrounds).map(([k,v])=>[k,Object.fromEntries(Object.entries(v).map(([n,s])=>[n,image(s)]))])),terrains=Object.fromEntries(Object.entries(DATA.terrains).map(([k,v])=>[k,{...v,jour:image(v.jour),nuit:image(v.nuit)}]));let id='01',mode='nuit',running=true,elapsed=0,last=null;const canvas=document.getElementById('view'),ctx=canvas.getContext('2d'),visible={sky:true,stars:true,clouds:true,halo:true,moon:true,sea:true,reflection:true,cliff:true};const names={sky:'Ciel seul',stars:'Étoiles animées',clouds:'Nuages · wrap overlay',halo:'Halo / shine animé',moon:'Lune / soleil fixe',sea:'Mer seule',reflection:'Reflet animé',cliff:'Falaise'};for(const [k,v]of Object.entries(names)){let l=document.createElement('label'),i=document.createElement('input');i.type='checkbox';i.checked=true;i.onchange=()=>visible[k]=i.checked;l.append(i,document.createTextNode(' '+v));document.getElementById('toggles').append(l)}function select(n){id=n;for(const b of document.querySelectorAll('.cards button'))b.classList.toggle('active',b.dataset.id===id);document.getElementById('audit').textContent=n+' — '+DATA.terrains[n].audit}for(const k of Object.keys(terrains)){const b=document.createElement('button');b.textContent=k+' · '+DATA.terrains[k].side;b.dataset.id=k;b.onclick=()=>select(k);document.getElementById('cards').append(b)}select(id);document.getElementById('mode').onchange=e=>mode=e.target.value;document.getElementById('pause').onclick=e=>{running=!running;e.target.textContent=running?'Pause':'Reprendre'};document.getElementById('reset').onclick=()=>elapsed=0;document.getElementById('png').onclick=()=>{const a=document.createElement('a');a.href=canvas.toDataURL();a.download='cote_'+id+'_'+mode+'.png';a.click()};function draw(i,x=0,y=0){if(i.complete&&i.naturalWidth)ctx.drawImage(i,x,y)}function render(t){if(last!==null&&running)elapsed+=t-last;last=t;const f=Math.floor(elapsed/80)%64,offset=-Math.floor(elapsed*.004)%960,b=bg[mode];ctx.clearRect(0,0,960,600);ctx.save();if(DATA.terrains[id].side==='droite'){ctx.translate(960,0);ctx.scale(-1,1)}if(visible.sky)draw(b.sky);if(visible.stars&&mode!=='jour')draw(stars[f]);if(visible.clouds){draw(b.clouds,offset);draw(b.clouds,offset+960)}if(mode==='nuit'){if(visible.halo)draw(halo[f]);if(visible.moon)draw(moon)}else if(visible.moon)draw(b.sun);if(visible.sea)draw(b.sea);if(visible.reflection)draw(reflets[mode==='nuit'?'lune':'soleil'][f],674,281);ctx.restore();if(visible.cliff)draw(terrains[id][mode==='nuit'?'nuit':'jour']);document.getElementById('clock').textContent='Phase '+String(f+1).padStart(2,'0')+'/64 · lumière : 5,12 s · nuages : '+offset+' px / 960 px';requestAnimationFrame(render)}requestAnimationFrame(render);</script></html>'''
(R/'apercu_references_calques_v2.html').write_text(html.replace('__DATA__',json.dumps(d)),encoding='utf8')
print('Gallery written')
